import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

smooth_l1_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void smooth_l1_loss_kernel(const float* predictions, const float* targets, float* out, float beta, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float diff = predictions[idx] - targets[idx];
        float adiff = fabsf(diff);
        float val = 0.0f;
        if (adiff < beta) {
            val = 0.5f * diff * diff / beta;
        } else {
            val = adiff - 0.5f * beta;
        }
        atomicAdd(out, val);
    }
}

torch::Tensor smooth_l1_loss_cuda(torch::Tensor predictions, torch::Tensor targets, float beta) {
    auto size = predictions.numel();
    auto out = torch::zeros({1}, predictions.options());

    const int block_size = 256;
    const int grid_size = (size + block_size - 1) / block_size;

    smooth_l1_loss_kernel<<<grid_size, block_size>>>(
        predictions.data_ptr<float>(),
        targets.data_ptr<float>(),
        out.data_ptr<float>(),
        beta,
        size
    );

    return out;
}
"""

smooth_l1_cpp_source = r"""
torch::Tensor smooth_l1_loss_cuda(torch::Tensor predictions, torch::Tensor targets, float beta);
"""

smooth_l1 = load_inline(
    name="smooth_l1",
    cpp_sources=[smooth_l1_cpp_source],
    cuda_sources=[smooth_l1_source],
    functions=["smooth_l1_loss_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.smooth_l1 = smooth_l1

    def forward(self, predictions, targets):
        # Compute aggregated smooth L1 on GPU
        out = self.smooth_l1.smooth_l1_loss_cuda(predictions, targets, 1.0)
        # Divide by total element count to match 'mean' reduction
        return out / predictions.numel()
